INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Bürosoftware wie Word immer für die Cloud erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal installierbar"}, {"text": "Ja", "correct": false, "because": "Cloud ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist entscheidend, wenn ich eine Software für Präsentationen auswähle?', 3, '[{"text": "Vorlagenvielfalt", "correct": true, "because": "Erleichtert Gestaltung"}, {"text": "Hohe Speichergröße", "correct": false, "because": "Nicht primär relevant"}, {"text": "Manuelle Formatierung", "correct": false, "because": "Zeitaufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen sind in einer Bürosoftware typischerweise enthalten?', 5, '[{"text": "Textverarbeitung", "correct": true, "because": "Für Dokumente essenziell"}, {"text": "Tabellenkalkulation", "correct": true, "because": "Für Datenanalyse"}, {"text": "Spieleentwicklung", "correct": false, "because": "Andere Software"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Nicht Bürosoftware"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bürosoftware unterstützt Teamarbeit. b) Sie ersetzt Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht ihre Aufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl einer Software für Dokumente?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Wichtig für Austausch"}, {"text": "Benutzerfreundlichkeit", "correct": false, "because": "Fördert Effizienz"}, {"text": "Grafikdesign", "correct": true, "because": "Für spezialisierte Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bürosoftware immer ein Abonnement erfordert?', 2, '[{"text": "Nein", "correct": true, "because": "Einmalkauf möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Tabellenkalkulationen entscheidend?', 3, '[{"text": "Formelunterstützung", "correct": true, "because": "Ermöglicht Berechnungen"}, {"text": "Textformatierung", "correct": false, "because": "Sekundär relevant"}, {"text": "Videoeinbettung", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine moderne Bürosoftware?', 5, '[{"text": "Cloud-Integration", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Automatische Updates", "correct": true, "because": "Hält Software aktuell"}, {"text": "Betriebssystemsteuerung", "correct": false, "because": "Andere Aufgabe"}, {"text": "Hohe Auflösung", "correct": false, "because": "Hardwareabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Bürosoftware kann mobil genutzt werden. b) Sie ist immer kostenlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Einsatz von Bürosoftware?', 4, '[{"text": "Internetverbindung", "correct": true, "because": "Offline-Nutzung möglich"}, {"text": "Lizenz", "correct": false, "because": "Für legale Nutzung nötig"}, {"text": "Kompatibles Gerät", "correct": false, "because": "Grundvoraussetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Bürosoftware nur für Windows geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Läuft auch auf macOS und Mobilgeräten"}, {"text": "Ja", "correct": false, "because": "Plattformübergreifend verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben kann ich mit Bürosoftware effektiv erledigen?', 4, '[{"text": "Datenanalyse", "correct": true, "because": "Tabellenkalkulationen"}, {"text": "Präsentationserstellung", "correct": true, "because": "Für Vorträge geeignet"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Bürosoftware immer Sicherheitsrisiken birgt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Risiken sind überschaubar mit Updates"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Verwaltung von E-Mails in Bürosoftware?', 3, '[{"text": "Filteroptionen", "correct": true, "because": "Fördert Organisation"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Nicht relevant"}, {"text": "Manuelle Archivierung", "correct": false, "because": "Zu aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bürosoftware unterstützt Makros. b) Sie ersetzt CAD-Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist für andere Zwecke"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen sichern die Nutzung von Bürosoftware ab?', 5, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Schließt Sicherheitslücken"}, {"text": "Antivirus-Integration", "correct": true, "because": "Schützt vor Malware"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nicht sicherheitsrelevant"}, {"text": "Manuelle Installation", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Lizenzierung von Bürosoftware unwichtig?', 3, '[{"text": "Nutzungsbedingungen", "correct": false, "because": "Definiert legale Nutzung"}, {"text": "Geräteanzahl", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Farbanpassung", "correct": true, "because": "Kein Lizenzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordert Bürosoftware immer hohe Hardwareleistung?', 3, '[{"text": "Nein", "correct": true, "because": "Läuft auch auf Standardgeräten"}, {"text": "Ja", "correct": false, "because": "Abhängig von Version"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bürosoftware für Datenbanken geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. Access für kleinere Datenbanken"}, {"text": "Nein", "correct": false, "because": "Teilweise unterstützt"}]'),
